import { fetchAPI } from "./api";

export const getProduits = () => fetchAPI("/products");
export const getProduitParId = (id) => fetchAPI(`/products/${id}`);
export const getCategories = () => fetchAPI("/products/categories");
export const getProduitsParCategorie = (cat) => fetchAPI(`/products/category/${cat}`);
